{
  "name": "S7通信伙伴节点",
  "name_en": "S7 Communication Partner",
  "manufacturer": "Siemens",
  "description": "一种基于西门子 S7 通信协议的工业通信节点，用于在 PLC、工业控制器或上位机之间通过工业以太网进行点对点数据交换。该类设备或通信端点可工作在主动连接或被动监听模式，适合实验室自动化与工业集成场景中的异步数据收发、联机状态监测和参数配置。",
  "description_en": "An industrial communication endpoint based on the Siemens S7 protocol, used for peer-to-peer data exchange between PLCs, industrial controllers, or supervisory computers over Industrial Ethernet. This type of device or communication node can operate in active or passive connection modes and is suitable for lab automation and industrial integration tasks involving asynchronous data transfer, connection status monitoring, and parameter configuration.",
  "tag_hints": [
    "Siemens S7",
    "PLC communication",
    "industrial Ethernet",
    "peer-to-peer data exchange",
    "active/passive connection",
    "asynchronous messaging",
    "automation integration"
  ],
  "actions": [
    {
      "action_name": "auto-create",
      "description": "创建通信伙伴节点。",
      "description_en": "Create the communication partner."
    },
    {
      "action_name": "auto-destroy",
      "description": "销毁通信伙伴节点。",
      "description_en": "Destroy the communication partner."
    },
    {
      "action_name": "auto-start",
      "description": "用默认参数启动通信伙伴节点。",
      "description_en": "Start the communication partner with default parameters."
    },
    {
      "action_name": "auto-start_to",
      "description": "按指定本地/远端地址和 TSAP 参数启动连接或监听。",
      "description_en": "Start the connection or listener with specified local/remote addresses and TSAP parameters."
    },
    {
      "action_name": "auto-stop",
      "description": "停止通信伙伴节点并断开连接。",
      "description_en": "Stop the communication partner and disconnect."
    },
    {
      "action_name": "auto-b_send",
      "description": "同步发送当前待发数据。",
      "description_en": "Send the current pending data synchronously."
    },
    {
      "action_name": "auto-b_recv",
      "description": "同步接收一帧数据。",
      "description_en": "Receive one data message synchronously."
    },
    {
      "action_name": "auto-as_b_send",
      "description": "异步发送当前待发数据。",
      "description_en": "Send the current pending data asynchronously."
    },
    {
      "action_name": "auto-check_as_b_send_completion",
      "description": "检查异步发送是否完成。",
      "description_en": "Check whether the asynchronous send has completed."
    },
    {
      "action_name": "auto-wait_as_b_send_completion",
      "description": "等待异步发送完成。",
      "description_en": "Wait for the asynchronous send to complete."
    },
    {
      "action_name": "auto-check_as_b_recv_completion",
      "description": "检查异步接收是否完成。",
      "description_en": "Check whether the asynchronous receive has completed."
    },
    {
      "action_name": "auto-set_param",
      "description": "设置通信参数。",
      "description_en": "Set communication parameters."
    },
    {
      "action_name": "auto-set_recv_callback",
      "description": "设置收到数据时的回调处理。",
      "description_en": "Set the callback for incoming data."
    },
    {
      "action_name": "auto-set_send_callback",
      "description": "设置异步发送完成时的回调处理。",
      "description_en": "Set the callback for completed asynchronous sends."
    },
    {
      "action_name": "auto-set_send_data",
      "description": "设置待发送的数据内容。",
      "description_en": "Set the data to be sent."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取运行/连接状态。",
      "description_en": "Get the run/connection status."
    },
    {
      "action_name": "auto-get_stats",
      "description": "获取通信统计信息。",
      "description_en": "Get communication statistics."
    },
    {
      "action_name": "auto-get_times",
      "description": "获取最近发送和接收操作时间。",
      "description_en": "Get the times of the most recent send and receive operations."
    },
    {
      "action_name": "auto-get_last_error",
      "description": "获取最后一次错误代码。",
      "description_en": "Get the last error code."
    },
    {
      "action_name": "auto-get_param",
      "description": "获取通信参数。",
      "description_en": "Get communication parameters."
    },
    {
      "action_name": "auto-get_recv_data",
      "description": "获取接收到的数据。",
      "description_en": "Get the received data."
    }
  ]
}

